// Auto-generated for the Unit Board — AWL Sublist 5
window.A5_DASHBOARD_UNITS = [{"unit":1,"theme":"academic – be able to V","cards":[{"w":"academic","p":"adj.","d":"about school or study","c":"學術的","s":"Her academic achievements are remarkable.","t":"她的學術成就非常卓越。"},{"w":"academics","p":"n.","d":"school work and studies","c":"學術","s":"She's been deeply involved in academics throughout her college life.","t":"她在大學生活中一直深深參與學術活動。"},{"w":"academy","p":"n.","d":"a school for special training","c":"學院","s":"The academy has a renowned history of excellence in the arts.","t":"這所學院在藝術方面有著著名的卓越歷史。"},{"w":"academically","p":"adv.","d":"in a way related to study","c":"在學術上","s":"He performed academically better this semester.","t":"他這學期在學術上的表現更好。"},{"w":"adjust to","p":"phr.","d":"to get used to something new","c":"調整至","s":"It took him some time to adjust to the new work environment.","t":"他花了一些時間調整到新的工作環境。"},{"w":"make adjustment","p":"phr.","d":"to make small changes","c":"做調整","s":"We may need to make adjustment to the plan based on the feedback.","t":"根據反饋，我們可能需要對計劃進行調整。"},{"w":"alter","p":"v.","d":"to change something","c":"改變","s":"They decided to alter the design after the prototype was tested.","t":"在原型測試後，他們決定改變設計。"},{"w":"alternation","p":"n.","d":"changing back and forth between two things","c":"交替","s":"The alternation between hot and cold water in the shower was abrupt.","t":"淋浴中的冷熱水交替很突然。"},{"w":"amend","p":"v.","d":"to make changes to a law or document","c":"修改","s":"They decided to amend the document before the final submission.","t":"他們決定在最終提交之前修改文件。"},{"w":"amendment","p":"n.","d":"a change made to a law or document","c":"修正案","s":"The amendment was passed by a majority vote in the parliament.","t":"修正案在議會中經多數票通過。"},{"w":"be aware of","p":"phr.","d":"to know that something exists","c":"意識到","s":"Citizens should be aware of their rights and responsibilities.","t":"公民應意識到他們的權利和責任。"},{"w":"beware","p":"v.","d":"to be careful of danger","c":"注意","s":"beware of slippery roads when driving in rainy conditions.","t":"雨天開車時要小心滑路。"},{"w":"unaware","p":"adj.","d":"not knowing about something","c":"沒意識到的","s":"He was completely unaware of the consequences of his actions.","t":"他完全沒有意識到他的行為的後果。"},{"w":"raise awareness","p":"phr.","d":"to help people know more about an issue","c":"提高意識","s":"The charity event was organized to raise awareness about children's health issues.","t":"這次慈善活動是為了提高人們對兒童健康問題的意識。"},{"w":"be capable of","p":"phr.","d":"having the ability to do something","c":"有能力的","s":"She's capable of achieving great things in her career.","t":"她在她的職業生涯中有能力取得偉大的成就。"},{"w":"uncapable","p":"adj.","d":"not able to do something","c":"無能力的","s":"Due to his health issues, he felt uncapable of taking on a full-time job.","t":"由於他的健康問題，他覺得無法承擔全職工作。"},{"w":"capacity","p":"n.","d":"the amount something can hold","c":"容量","s":"The stadium has a capacity of 20,000 spectators.","t":"這個體育場的容量為20,000名觀眾。"},{"w":"enable to V","p":"phr.","d":"to make someone able to do something","c":"使能夠","s":"Advanced technology will enable us to explore deeper parts of the ocean.","t":"先進的技術將使我們能夠探索海洋的更深部分。"},{"w":"be able to V","p":"phr.","d":"can do something","c":"能夠","s":"With enough training, you will be able to complete the marathon.","t":"經過足夠的訓練，您將能夠完成馬拉松。"}]},{"unit":2,"theme":"ability to V – energy","cards":[{"w":"ability to V","p":"phr.","d":"the skill or power to do something","c":"能力","s":"Her ability to grasp complex concepts quickly is commendable.","t":"她能迅速理解複雜概念的能力值得稱讚。"},{"w":"challenge","p":"v.","d":"to test someone's ability; to question something","c":"挑戰","s":"The recent economic downturn will challenge businesses to adapt.","t":"近期的經濟衰退將挑戰企業的適應能力。"},{"w":"overcome a challenge","p":"phr.","d":"to solve a difficult problem","c":"克服挑戰","s":"With determination and hard work, he managed to overcome a challenge.","t":"憑著決心和努力，他成功克服了挑戰。"},{"w":"clause","p":"n.","d":"a part of a sentence with a subject and verb","c":"子句","s":"Make sure you read every clause of the contract before signing it.","t":"在簽署合同之前，請確保您閱讀了每一條款。"},{"w":"compound","p":"n.","d":"a substance made of two or more elements","c":"化合物","s":"The scientist isolated a new compound from the plant extract.","t":"科學家從植物提取物中分離出了一種新的化合物。"},{"w":"conflict","p":"v.","d":"to be different and not able to exist together","c":"衝突","s":"Personal interests might conflict with professional duties.","t":"個人興趣可能與專業職責衝突。"},{"w":"conflict","p":"n.","d":"a serious disagreement or fight","c":"衝突","s":"The ongoing conflict between the two nations is of global concern.","t":"兩國之間的持續衝突引起了全球的關注。"},{"w":"consult","p":"v.","d":"to ask an expert for advice","c":"諮詢","s":"Before making a decision, she decided to consult her family.","t":"做決定之前，她決定諮詢她的家人。"},{"w":"consultation","p":"n.","d":"a meeting to get advice","c":"諮詢","s":"After a lengthy consultation with his team, the manager outlined the new strategy.","t":"經過與他的團隊長時間的諮詢後，經理概述了新的策略。"},{"w":"counsel","p":"n.","d":"advice","c":"忠告","s":"She sought the counsel of her mentor before changing her career path.","t":"她在改變職業道路之前尋求了導師的忠告。"},{"w":"counselling","p":"n.","d":"professional help with personal problems","c":"輔導","s":"He attended several counselling sessions to cope with his stress.","t":"為了應對壓力，他參加了幾次輔導課程。"},{"w":"contact","p":"v.","d":"to call or write to someone","c":"聯繫","s":"Please contact the supplier if you have any queries.","t":"如果您有任何疑問，請聯繫供應商。"},{"w":"contact","p":"n.","d":"communication with someone","c":"聯繫","s":"She lost all contact with her college friends after graduation.","t":"她畢業後與大學朋友失去了所有聯繫。"},{"w":"decline","p":"v.","d":"to become less or worse","c":"衰退","s":"The quality of the product seemed to decline over the years.","t":"這款產品的質量似乎隨著時間的推移而下降。"},{"w":"decline in","p":"n./phr.","d":"a decrease in something","c":"下降","s":"There's been a steady decline in sales over the past six months.","t":"過去六個月，銷售一直在下降。"},{"w":"discretion","p":"n.","d":"the freedom to decide what to do","c":"判斷","s":"Use your discretion when discussing sensitive topics with clients.","t":"與客戶討論敏感話題時請謹慎行事。"},{"w":"draft","p":"n.","d":"a first version of a piece of writing","c":"草稿","s":"After several edits, the final version was much improved from the original draft.","t":"經過幾次編輯後，最終版本比原始草稿有很大改進。"},{"w":"draft","p":"v.","d":"to write a first version of something","c":"起草","s":"She was asked to draft a proposal for the upcoming project.","t":"她被要求為即將到來的項目起草一份提案。"},{"w":"energy","p":"n.","d":"power used to make machines work","c":"能源","s":"The country is looking for alternative energy sources to reduce its dependence on fossil fuels.","t":"該國正在尋找替代能源，以減少對化石燃料的依賴。"}]},{"unit":3,"theme":"energize – expose to","cards":[{"w":"energize","p":"v.","d":"to give energy to someone or something","c":"給予能量","s":"The motivational speech seemed to energize the entire team.","t":"激勵性的演講似乎為整個團隊注入了能量。"},{"w":"energetic","p":"adj.","d":"full of energy","c":"精力充沛的","s":"Even after a long day, she remains energetic and enthusiastic.","t":"即使經過漫長的一天，她仍然保持充滿活力和熱情。"},{"w":"enforce","p":"v.","d":"to make people obey a law","c":"執行","s":"The government has introduced new measures to enforce tax regulations.","t":"政府已引入新措施來執行稅收規定。"},{"w":"reinforce","p":"v.","d":"to make something stronger","c":"加強","s":"Practicing daily will reinforce your language skills.","t":"每天練習會加強你的語言技能。"},{"w":"enforcement","p":"n.","d":"making sure people obey laws","c":"執行","s":"enforcement of the new rules will begin next week.","t":"下週將開始執行新規則。"},{"w":"entity","p":"n.","d":"something that exists on its own, like a company","c":"實體","s":"The subsidiary operates as a separate entity from the main corporation.","t":"子公司作為主要公司的獨立實體運作。"},{"w":"entities","p":"n.","d":"things that exist on their own","c":"實體","s":"Multiple entities collaborated on the large-scale project.","t":"多個實體合作進行了大規模的項目。"},{"w":"equivalent","p":"adj./n.","d":"equal in value or meaning","c":"相當的/等價物","s":"The word has no direct equivalent in the other language.","t":"這個詞在另一種語言中沒有直接等價物。"},{"w":"be equivalent to","p":"phr.","d":"to be equal to something","c":"等於","s":"The value of this old coin is equivalent to a small fortune.","t":"這枚古老的硬幣的價值相當於一筆小財富。"},{"w":"evolve","p":"v.","d":"to change slowly over time","c":"進化","s":"The software continues to evolve with each update.","t":"該軟件在每次更新時都在進化。"},{"w":"evolved","p":"adj.","d":"developed over time","c":"進化的","s":"Modern birds are believed to be the evolved descendants of dinosaurs.","t":"人們認為現代鳥類是恐龍的進化後裔。"},{"w":"evolution","p":"n.","d":"slow change over a long time","c":"進化","s":"The evolution of technology over the past decade has been astounding.","t":"過去十年技術的進化令人震驚。"},{"w":"expand","p":"v.","d":"to make something bigger","c":"擴大","s":"The company plans to expand its operations into European markets.","t":"公司計劃將其業務擴展到歐洲市場。"},{"w":"expansion","p":"n.","d":"the act of becoming bigger","c":"擴張","s":"The city is experiencing rapid expansion due to the influx of businesses.","t":"由於業務湧入，該市正在經歷迅速的擴張。"},{"w":"expansive","p":"adj.","d":"covering a large area","c":"廣闊的","s":"The estate offers an expansive view of the mountains.","t":"該莊園提供了山脈的廣闊景觀。"},{"w":"extend","p":"v.","d":"to make something longer or larger","c":"延伸","s":"We decided to extend our stay by two more days.","t":"我們決定再延長兩天的停留。"},{"w":"extension","p":"n.","d":"extra time given to do something","c":"延期","s":"She requested an extension for her project deadline.","t":"她要求延長她的項目截止日期。"},{"w":"extensive","p":"adj.","d":"covering a large area; a lot of","c":"廣泛的","s":"His knowledge of the subject is truly extensive.","t":"他對該主題的了解確實很廣泛。"},{"w":"expose to","p":"v.","d":"to put someone in contact with something","c":"暴露於","s":"It's important not to expose to sensitive plants to direct sunlight.","t":"重要的是不要將敏感植物暴露於直射陽光下。"}]},{"unit":4,"theme":"be exposed to – license","cards":[{"w":"be exposed to","p":"phr.","d":"to be in contact with something","c":"被暴露於","s":"The workers were exposed to hazardous chemicals without proper protection.","t":"工人在沒有適當保護的情況下被有害化學品暴露。"},{"w":"exposure to","p":"n.","d":"contact with something","c":"接觸","s":"Prolonged exposure to loud noises can harm your hearing.","t":"長時間接觸噪音可能會損害您的聽力。"},{"w":"external","p":"adj.","d":"outside something","c":"外部的","s":"The building suffered only external damage from the storm.","t":"該建築物只受到暴風雨的外部損害。"},{"w":"externalize","p":"v.","d":"to show feelings or ideas outside yourself","c":"外在化","s":"He tends to externalize his emotions through painting.","t":"他傾向於通過繪畫外在化他的情感。"},{"w":"internal","p":"adj.","d":"inside something","c":"內部的","s":"The committee is handling the matter as an internal issue.","t":"委員會正在將該事宜作為一個內部問題來處理。"},{"w":"internalize","p":"v.","d":"to make an idea part of your beliefs","c":"內化","s":"Over time, she began to internalize the criticism, leading to lower self-esteem.","t":"隨著時間的推移，她開始內化這些批評，導致自尊心降低。"},{"w":"facilitate","p":"v.","d":"to make something easier to happen","c":"促使","s":"Modern technology can facilitate quicker communication between countries.","t":"現代技術可以促使國家之間更快地通信。"},{"w":"fundamental","p":"adj.","d":"basic and very important","c":"基本的","s":"Respecting others is a fundamental principle in any society.","t":"尊重他人是任何社會的基本原則。"},{"w":"generate","p":"v.","d":"to produce something","c":"產生","s":"The new policy is expected to generate a lot of public interest.","t":"預期新政策將產生很大的公共興趣。"},{"w":"generate electricity","p":"phr.","d":"to produce electric power","c":"產電","s":"Solar panels are used to generate electricity from sunlight.","t":"太陽能板用於從陽光中產電。"},{"w":"generated","p":"v.","d":"produced","c":"已產生","s":"The concert generated a huge amount of money for charity.","t":"音樂會為慈善事業籌集了大量資金。"},{"w":"generation","p":"n.","d":"all people born at about the same time","c":"一代","s":"The older generation often finds it hard to understand the mindset of the youth.","t":"老一代通常很難理解年輕人的思維方式。"},{"w":"image","p":"n.","d":"a picture","c":"影像","s":"The company wants to improve its public image.","t":"該公司希望提高其公共形象。"},{"w":"imagine","p":"v.","d":"to form a picture in your mind","c":"想像","s":"Can you imagine living without a phone for a month?","t":"你能想像一個月不用手機嗎？"},{"w":"imaginary","p":"adj.","d":"not real; only in the mind","c":"虛構的","s":"Unicorns are imaginary creatures often depicted in children's stories.","t":"獨角獸是兒童故事中經常描繪的虛構生物。"},{"w":"imaginative","p":"adj.","d":"good at thinking of new ideas","c":"有想像力的","s":"She's one of the most imaginative writers of her generation.","t":"她是她這一代人中最有想像力的作家之一。"},{"w":"liberal","p":"adj.","d":"open to new ideas; supporting freedom","c":"自由的","s":"His liberal views on marriage and relationships often surprised conservative listeners.","t":"他對婚姻和關係的自由觀點經常使保守的聽眾感到驚訝。"},{"w":"liberty","p":"n.","d":"freedom","c":"自由","s":"Every citizen should have the liberty to express their opinions freely.","t":"每個公民都應該有自由表達自己意見的自由。"},{"w":"license","p":"v.","d":"to give official permission","c":"授權","s":"The government will license the company to operate within its borders.","t":"政府將授權該公司在其邊界內運營。"}]},{"unit":5,"theme":"license – monitoring","cards":[{"w":"license","p":"n.","d":"an official paper that gives permission","c":"許可證","s":"Before you can drive, you'll need to obtain a driving license.","t":"在您開車之前，您需要獲得駕駛許可證。"},{"w":"logic","p":"n.","d":"clear and sensible thinking","c":"邏輯","s":"The logic behind his decision was difficult for others to understand.","t":"其他人很難理解他的決定背後的邏輯。"},{"w":"logical","p":"adj.","d":"sensible and reasonable","c":"合邏輯的","s":"It's only logical to assume that if the weather is cold, one should wear a coat.","t":"假設天氣寒冷，人們應該穿外套，這只是合邏輯的。"},{"w":"margin","p":"n.","d":"the empty space at the side of a page","c":"邊緣","s":"Keep your notes in the margin of the page.","t":"把你的筆記放在頁面的邊緣。"},{"w":"marginal","p":"adj.","d":"small and not very important","c":"邊緣的","s":"There's only a marginal difference between the two products.","t":"這兩種產品之間只有邊緣的差異。"},{"w":"marginalized","p":"adj.","d":"treated as unimportant by society","c":"被邊緣化的","s":"marginalized groups often face more challenges in society.","t":"被邊緣化的群體在社會上經常面臨更多的挑戰。"},{"w":"medical","p":"adj.","d":"about medicine and health","c":"醫學的","s":"He decided to pursue a medical career after his father's illness.","t":"他的父親生病後，他決定追求醫學職業。"},{"w":"medicine","p":"n.","d":"a substance used to treat illness","c":"藥物","s":"The doctor prescribed a new medicine to treat her condition.","t":"醫生開了一種新藥來治療她的病情。"},{"w":"medication","p":"n.","d":"medicine you take to treat an illness","c":"藥物治療","s":"He forgot to take his medication this morning, so he felt dizzy.","t":"他今天早上忘了吃藥，所以感到暈眩。"},{"w":"mental","p":"adj.","d":"about the mind","c":"心理的","s":"It's important to take care of both physical and mental health.","t":"重要的是要照顧身體和心理健康。"},{"w":"mentally","p":"adv.","d":"in the mind","c":"心理上地","s":"She felt mentally exhausted after the intense debate.","t":"經過激烈的辯論後，她感到心理上很累。"},{"w":"physical","p":"adj.","d":"about the body","c":"身體的","s":"Regular exercise is important for physical well-being.","t":"定期運動對身體健康很重要。"},{"w":"modify","p":"v.","d":"to change something a little","c":"修改","s":"They decided to modify the plan to accommodate the new changes.","t":"他們決定修改計劃以適應新的變化。"},{"w":"modified","p":"adj.","d":"changed a little","c":"已修改的","s":"The modified version of the software has many new features.","t":"軟件的修改版本有許多新功能。"},{"w":"genetically modified","p":"adj.","d":"having changed genes","c":"基因改造的","s":"Many people debate the safety of genetically modified foods.","t":"許多人質疑基因改造食品的安全性。"},{"w":"modification","p":"n.","d":"a small change","c":"修改","s":"Several modifications to the original design were made to improve performance.","t":"對原始設計進行了幾次修改以提高性能。"},{"w":"monitor","p":"n.","d":"a screen that shows pictures","c":"監視器","s":"She glanced at the monitor to check the surveillance footage.","t":"她看了一眼監視器以檢查監控錄像。"},{"w":"monitor","p":"v.","d":"to watch and check something over time","c":"監控","s":"They hired a professional to monitor their network for security breaches.","t":"他們聘請了一名專家來監控他們的網絡，以防止安全漏洞。"},{"w":"monitoring","p":"n.","d":"watching and checking something","c":"監控","s":"Regular monitoring of the servers ensures they operate at optimal performance.","t":"定期監控伺服器可確保其達到最佳性能。"}]},{"unit":6,"theme":"network – precision","cards":[{"w":"network","p":"n.","d":"a large system of connected people or things","c":"網絡","s":"The company has a vast network of suppliers and distributors.","t":"該公司有一個龐大的供應商和經銷商網絡。"},{"w":"networking","p":"n.","d":"meeting people who can help you at work","c":"建立人脈","s":"networking is essential for young professionals aiming to climb the corporate ladder.","t":"對於希望在公司晉升的年輕專業人士來說，建立人脈是必不可少的。"},{"w":"social networking","p":"n.","d":"using websites to connect with people","c":"社交網絡","s":"Many people spend hours on social networking sites to keep up with friends and current events.","t":"許多人在社交網站上花費數小時，以與朋友保持聯繫並了解時事。"},{"w":"notion","p":"n.","d":"an idea or belief","c":"概念","s":"She had a vague notion of what the job entailed, but wasn't sure about the specifics.","t":"她對工作的內容有一個模糊的概念，但不確定具體情況。"},{"w":"note","p":"n.","d":"a short piece of writing to help you remember","c":"筆記","s":"He took a quick note to remind himself of the meeting's main points.","t":"他快速記下筆記，以提醒自己會議的主要要點。"},{"w":"note","p":"v.","d":"to notice; to pay attention to","c":"注意","s":"Please note that the deadline for submissions is next Friday.","t":"請注意，提交的截止日期是下周五。"},{"w":"notify","p":"v.","d":"to tell someone officially","c":"通知","s":"The school will notify parents of any changes to the schedule.","t":"如有任何課程變動，學校將通知家長。"},{"w":"be notified","p":"phr.","d":"to be told officially","c":"被通知","s":"We were notified of the decision yesterday.","t":"我們昨天被通知了這一決定。"},{"w":"notification","p":"n.","d":"an official message telling you something","c":"通知","s":"The system automatically sends a notification when a new update is available.","t":"當有新更新可用時，系統會自動發送通知。"},{"w":"objective","p":"adj.","d":"fair; not influenced by feelings","c":"客觀的","s":"The research aims to provide an objective assessment of the situation.","t":"該研究旨在提供對情況的客觀評估。"},{"w":"objective = goal","p":"n.","d":"a goal; something you want to achieve","c":"目標","s":"The primary objective of the program is to increase literacy rates.","t":"該計劃的主要目標是提高識字率。"},{"w":"orient","p":"v.","d":"to point or direct toward something","c":"定位","s":"The building is oriented to maximize sunlight during the winter months.","t":"該建築物的定位是在冬季最大化陽光。"},{"w":"oriental","p":"adj.","d":"from East Asia","c":"東方的","s":"The museum features an impressive collection of oriental art.","t":"博物館展出了令人印象深刻的東方藝術收藏。"},{"w":"-oriented","p":"adj.","d":"focused on something","c":"以...為導向","s":"The company is now more customer--oriented.","t":"該公司現在更以顧客為導向。"},{"w":"orientation","p":"n.","d":"introduction to a new place; direction","c":"定位；方向","s":"The orientation of the new employees will take place on Monday.","t":"新員工的定位將在星期一進行。"},{"w":"perspective","p":"n.","d":"a way of looking at something","c":"透視；觀點","s":"From an environmental perspective, the new policy is a step forward.","t":"從環境的角度看，新政策是向前邁進的一步。"},{"w":"precise","p":"adj.","d":"exact and accurate","c":"精確的","s":"The scientist made precise measurements to ensure the accuracy of the experiment.","t":"為確保實驗的準確性，科學家進行了精確的測量。"},{"w":"precisely","p":"adv.","d":"exactly","c":"精確地","s":"The artifact was precisely dated to the 5th century BC.","t":"這件文物被精確地定於公元前5世紀。"},{"w":"precision","p":"n.","d":"the quality of being exact","c":"精確度","s":"Engineers must work with utmost precision to ensure the safety of the structures.","t":"工程師必須極其精確地工作以確保結構的安全。"}]},{"unit":7,"theme":"prime – stylish","cards":[{"w":"prime","p":"adj.","d":"main; most important","c":"主要的","s":"The prime reason for his visit was to discuss the new contract.","t":"他訪問的主要原因是討論新合同。"},{"w":"primary","p":"adj.","d":"main; most important","c":"主要的","s":"The primary focus of the study was on the effects of climate change.","t":"這項研究的主要重點是氣候變化的影響。"},{"w":"psychology","p":"n.","d":"the study of the mind and behavior","c":"心理學","s":"He majored in psychology at the university and now works as a therapist.","t":"他在大學主修心理學，現在擔任治療師。"},{"w":"pursue","p":"v.","d":"to try to get or do something","c":"追求","s":"She decided to pursue a career in medicine after volunteering at a local hospital.","t":"在當地醫院擔任志願者後，她決定追求醫學職業。"},{"w":"pursuit","p":"n.","d":"the act of trying to get something","c":"追求","s":"The pursuit of happiness is considered an inalienable right.","t":"追求幸福被認為是不可剝奪的權利。"},{"w":"in pursuit of","p":"phr.","d":"trying to get or achieve something","c":"追求","s":"Many students travel abroad in pursuit of better educational opportunities.","t":"許多學生出國追求更好的教育機會。"},{"w":"ratio","p":"n.","d":"a number that compares two amounts","c":"比率","s":"The ratio of teachers to students in that school is 1:20.","t":"那所學校的教師與學生之比是1:20。"},{"w":"rate","p":"n.","d":"how fast or how often something happens","c":"率","s":"The exchange rate fluctuates daily based on economic factors.","t":"匯率每天都會根據經濟因素波動。"},{"w":"rate","p":"v.","d":"to judge how good something is","c":"評價","s":"Critics rate the movie highly, citing its innovative storyline and excellent acting.","t":"評論家高度評價了這部電影，稱讚其創新的故事情節和出色的表演。"},{"w":"reject","p":"v.","d":"to refuse to accept something","c":"拒絕","s":"Due to quality concerns, the company decided to reject the entire batch of products.","t":"由於質量問題，公司決定拒絕整批產品。"},{"w":"rejected","p":"adj.","d":"not accepted","c":"被拒絕的","s":"The rejected manuscript later became a best-seller after another publisher took a chance on it.","t":"被拒絕的手稿後來成為了暢銷書，因為另一家出版社冒險出版了它。"},{"w":"rejection","p":"n.","d":"refusing to accept something","c":"拒絕","s":"The author faced several rejections before his novel was finally published.","t":"作者的小說最終出版之前，他遭受了多次拒絕。"},{"w":"revenue","p":"n.","d":"money a company or government earns","c":"收入","s":"The company reported a 20% increase in annual revenue last year.","t":"該公司去年報告年收入增長20%。"},{"w":"stable","p":"adj.","d":"not likely to change","c":"穩定的","s":"The economy has remained stable despite global challenges.","t":"儘管面臨全球挑戰，經濟仍然保持穩定。"},{"w":"unstable","p":"adj.","d":"likely to change suddenly","c":"不穩定的","s":"The political situation in the region is unstable and can change rapidly.","t":"該地區的政治局勢是不穩定的，且可能迅速變化。"},{"w":"stability","p":"n.","d":"the state of not changing","c":"穩定性","s":"Investors are looking for stability in the financial markets before making large investments.","t":"投資者在進行大量投資之前正在尋找金融市場的穩定性。"},{"w":"style","p":"n.","d":"a particular way of doing something","c":"風格","s":"The artist has a unique style that sets her apart from her contemporaries.","t":"該藝術家具有獨特的風格，使她與同時代的人區別開來。"},{"w":"style","p":"v.","d":"to design or arrange in a certain way","c":"設計","s":"She styled the interior of the house with a mix of modern and traditional elements.","t":"她使用現代和傳統元素的混合設計了房屋的內部。"},{"w":"stylish","p":"adj.","d":"fashionable and attractive","c":"有風格的","s":"The new line of clothing is not only comfortable but also very stylish.","t":"新的服裝系列不僅舒適，而且非常有風格。"}]},{"unit":8,"theme":"submit to – whereas","cards":[{"w":"submit to","p":"v. phr.","d":"to give something to someone for a decision","c":"提交至","s":"Authors must submit to their manuscripts to the editorial board for review.","t":"作者必須將他們的手稿提交至編輯委員會進行審查。"},{"w":"be submitted","p":"v. past","d":"to have been given in officially","c":"已提交的","s":"The report was submitted on time, despite the tight deadline.","t":"儘管時間緊迫，報告還是準時提交了。"},{"w":"substitution","p":"n.","d":"using one thing in place of another","c":"替代","s":"Using honey as a substitution for sugar is a healthier option in recipes.","t":"在食譜中使用蜜糖替代糖是一個更健康的選擇。"},{"w":"sustain","p":"v.","d":"to keep something going","c":"維持","s":"The city has been trying to sustain its historic landmarks for future generations.","t":"該城市一直在努力維護其歷史地標，以供後代參觀。"},{"w":"sustainable","p":"adj.","d":"able to continue without harming nature","c":"可持續的","s":"sustainable farming practices are vital for protecting the environment.","t":"可持續的農業實踐對於保護環境至關重要。"},{"w":"sustainability","p":"n.","d":"the ability to continue without harm","c":"可持續性","s":"The conference focused on sustainability in urban planning.","t":"會議聚焦於城市規劃的可持續性。"},{"w":"symbol","p":"n.","d":"a sign or picture that stands for something","c":"符號","s":"The dove is a universal symbol of peace.","t":"和平鴿是和平的普遍符號。"},{"w":"be symbolic of","p":"phr.","d":"to stand for an idea","c":"象徵","s":"The empty throne in the painting is symbolic of the missing leadership in the kingdom.","t":"畫中的空王座象徵著王國中缺失的領導力。"},{"w":"symbolize","p":"v.","d":"to stand for an idea","c":"象徵","s":"White roses often symbolize purity and innocence.","t":"白玫瑰通常象徵純潔和無辜。"},{"w":"target","p":"n.","d":"something you aim to achieve","c":"目標","s":"The company has set a target of increasing sales by 15% this year.","t":"該公司設定了今年銷售增長15%的目標。"},{"w":"transit","p":"n.","d":"being moved from one place to another","c":"過境，交通","s":"The goods are currently in transit and will arrive at the port tomorrow.","t":"貨物目前正在過境，將於明天到達港口。"},{"w":"transit","p":"v.","d":"to pass through a place","c":"經過","s":"The migratory birds transit through this region every spring.","t":"每年春天，候鳥都會經過這個地區。"},{"w":"transition","p":"n.","d":"a change from one state to another","c":"轉變，過渡","s":"The country is in a transition from a dictatorship to a democratic system.","t":"這個國家正在從獨裁制轉變為民主制度。"},{"w":"transitional","p":"adj.","d":"happening during a change","c":"過渡的","s":"transitional governments often face challenges in ensuring stability.","t":"過渡政府在確保穩定性方面經常面臨挑戰。"},{"w":"trend","p":"n.","d":"the way something is changing","c":"趨勢","s":"The current trend in fashion leans towards more sustainable practices.","t":"當前的時尚趨勢傾向於更加可持續的做法。"},{"w":"trendy","p":"adj.","d":"fashionable","c":"時髦的","s":"Wearing vintage clothes has become very trendy among young people.","t":"年輕人中間，穿復古衣服已經變得非常時髦。"},{"w":"version","p":"n.","d":"a slightly different form of something","c":"版本","s":"I prefer the original version of the song to the remix.","t":"我更喜歡這首歌的原始版本，而不是混音版本。"},{"w":"welfare","p":"n.","d":"help for people's health and happiness","c":"福利","s":"The new policy aims to improve the welfare of the country's elderly population.","t":"新政策旨在改善該國老年人口的福利。"},{"w":"whereas","p":"conj.","d":"while on the other hand","c":"然而","s":"Some people love the hustle and bustle of the city, whereas others prefer the quiet of the countryside.","t":"有些人喜歡城市的喧囂，而其他人則更喜歡鄉村的寧靜。"}]}];
